
'use strict';
const $=s=>document.querySelector(s), KEY='miseno-docentes-v1';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({notes:[],review:false,planReview:false,academic:false,started:false});
let selectedProfile=null;
let state=initial(),page='launch',student='tomi',tab='activities',query='',groupFilter='all',situationFilter='all',toastTimer;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.notes))state={...initial(),...s}}catch(e){}
const pupils=[{id:'tomi',name:'Tomás',short:'Tomi',initial:'T',subject:'Matemática',activity:'Fracciones · Situaciones de fútbol',color:'#eee9fa',status:'Revisar adaptación'},{id:'joaquin',name:'Joaquín',short:'Joaquín',initial:'J',subject:'Matemática',activity:'Fracciones · Apoyo visual',color:'#e2eff4',status:'Necesita acompañamiento'},{id:'sofia',name:'Sofía',short:'Sofía',initial:'S',subject:'Ciencias',activity:'Las plantas · Proyecto de huerta',color:'#e0f1e8',status:'Actividad en curso'},{id:'bruno',name:'Bruno',short:'Bruno',initial:'B',subject:'Lengua',activity:'La arquera · Comprensión del cuento',color:'#f7e8df',status:'Actividad en curso'},{id:'emma',name:'Emma',short:'Emma',initial:'E',subject:'Historia',activity:'La colonia · Exploración guiada',color:'#e9e6f8',status:'Actividad en curso'},{id:'mateo',name:'Mateo',short:'Mateo',initial:'M',subject:'Ciencias',activity:'Las plantas · Observación',color:'#e0eee8',status:'Sin nuevos registros'}];
const iconPaths={group:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',situations:'<rect x="4" y="3" width="16" height="18" rx="4"/><path d="M8 8h8m-8 4h5m-5 4h8"/>',paths:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v7a5 5 0 0 0 5 5h5M8 5h5a5 5 0 0 1 5 5v7"/>',projects:'<rect x="3" y="4" width="7" height="7" rx="2"/><rect x="14" y="4" width="7" height="7" rx="2"/><rect x="3" y="15" width="7" height="7" rx="2"/><path d="M14 18h7m-3-3v7"/>'};
function icon(id){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[id]||iconPaths.situations}</svg>`}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('No se pudo guardar en el navegador. Se conserva durante esta sesión.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500)}
function pending(){return Number(!state.review)+Number(!state.academic)}
function nav(){const names={group:'Grupo',paths:'Recorridos',projects:'Proyectos'};$('#nav').innerHTML=Object.entries(names).map(([id,name])=>`<button data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(id==='students'?'group':id)}${name}</button>`).join('')}

function title(a,b,extra=''){return `<div class="heading"><div><div class="eyebrow">Miseño · Grupo A</div><h1 id="page-title" tabindex="-1">${a}</h1><p>${b}</p></div>${extra}</div>`}
function pupil(id=student){return pupils.find(p=>p.id===id)||pupils[0]}
function avatar(p){return `<span class="avatar" style="background:${p.color}">${p.initial}</span>`}
function status(p){if(p.id==='tomi')return state.review?'En revisión':state.started?'En atención':p.status;if(p.id==='joaquin'&&state.academic)return 'Intervención realizada';return p.status}
function openPupil(id){student=id;page='paths';tab='activities';render(true)}
function group(){const list=pupils.filter(p=>(p.name+' '+p.short+' '+p.subject).toLowerCase().includes(query.toLowerCase()));return title('Grupo A','Actividades actuales y datos de los alumnos.')+`<div class="group-layout ${selectedProfile?'has-profile':''}"><section class="card"><div class="toolbar"><input type="search" id="search" aria-label="Buscar alumno o materia" placeholder="Buscar alumno o materia" value="${esc(query)}"></div><div class="student-list">${list.map(p=>`<button class="student" data-profile="${p.id}" aria-expanded="${selectedProfile===p.id}" aria-controls="student-profile"><div class="split">${avatar(p)}<div><strong>${p.name}</strong><div class="small muted">${p.subject}</div></div></div><p>${p.activity}</p><span class="tag">${status(p)}</span></button>`).join('')||'<p class="empty">No hay alumnos que coincidan con la búsqueda.</p>'}</div></section><aside id="student-profile" aria-label="Ficha del alumno" ${selectedProfile?'':'hidden'}>${selectedProfile?profilePanel(pupil(selectedProfile)):''}</aside></div>`}
function profilePanel(p){return `<section class="card profile-panel"><div class="row"><div class="split">${avatar(p)}<h2 id="profile-heading" tabindex="-1">${p.name}</h2></div><button class="close" data-action="close-profile" aria-label="Cerrar ficha del alumno">×</button></div><dl><dt>Nombre de uso</dt><dd>${p.short}</dd><dt>Grupo</dt><dd>Grupo A · Primaria</dd><dt>Actividad actual</dt><dd>${p.activity}</dd><dt>Estado</dt><dd>${status(p)}</dd></dl><p class="small muted">Otros datos personales: sin cargar.</p><div class="actions"><button class="btn secondary" data-student="${p.id}">Ver recorrido</button><button class="btn ghost" data-history="${p.id}">Ver historial</button></div></section>`}

function situations(){const items=[{id:'tomi',title:'Dificultad persistente · Revisar adaptación',desc:'Contrastar las fuentes utilizadas para personalizar sus actividades.',state:state.review?'review':state.started?'active':'pending',label:state.review?'En revisión':state.started?'En atención':'Pendiente'},{id:'joaquin',title:'El tutor solicita acompañamiento',desc:'Necesita apoyo con fracciones después de varios métodos de explicación.',state:state.academic?'done':'pending',label:state.academic?'Intervención realizada':'Pendiente'}].filter(i=>situationFilter==='all'||i.state===situationFilter);return title('Situaciones para acompañar','Revisá el contexto antes de decidir cómo intervenir.')+`<div class="toolbar"><label for="situation-filter" style="margin:0">Mostrar</label><select id="situation-filter"><option value="all">Todas las situaciones</option><option value="pending">Pendientes</option><option value="active">En atención</option><option value="review">En revisión</option><option value="done">Intervenciones realizadas</option></select></div><section class="card"><h2>Seguimiento del grupo</h2>${items.map(i=>`<article class="situation"><div><span class="tag ${i.state==='done'?'green':'amber'}">${i.label}</span><h3>${pupil(i.id).name} · ${i.title}</h3><p class="muted">${i.desc}</p><p class="small muted">10 nov · Registro de Miseño</p></div><button class="btn secondary" data-student="${i.id}">Abrir situación</button></article>`).join('')||'<p class="empty">No hay situaciones con este estado.</p>'}</section>`}
function sourcePanel(){return `<section class="card"><div class="row"><h2>Información utilizada</h2><span class="tag amber">Versiones diferentes</span></div><p class="muted" style="margin-top:10px">Estos registros refieren al mismo interés, desde momentos y contextos distintos.</p><div class="evidence"><article class="source-card family"><span class="tag green">Familia · Declaración</span><blockquote>“A Tomi le gusta el fútbol y jugar con autitos”.</blockquote><p class="small">2 nov · Aporte familiar<br>Contexto: intereses en casa.</p></article><article class="source-card"><span class="tag lilac">Alumno · Declaración explícita</span><blockquote>“No me gusta el fútbol. ¿Podemos hacer otra cosa?”.</blockquote><p class="small">9 nov · Conversación con el tutor<br>Contexto: actividad de fracciones.</p></article></div><div class="callout">Ninguna versión reemplaza a la otra. La fecha y el contexto pueden ayudar a entender la diferencia.</div><h3 style="margin-top:24px">Cómo lo está interpretando Miseño</h3><p class="muted" style="margin-top:10px">“Se utilizaron situaciones de fútbol a partir del interés declarado por la familia. Se registró necesidad de apoyo en varias actividades”.</p><div class="callout amber"><strong>Explicación incompleta</strong><br>No está disponible cómo se ponderó la declaración posterior del alumno ni por qué se mantuvo esa temática. La causa de la dificultad sigue abierta.</div></section>`}
function activities(){const tomi=student==='tomi';return `<section class="card"><h2>Actividades y apoyos utilizados</h2><p class="muted" style="margin-top:10px">${tomi?'La temática utilizada puede ser un aspecto a revisar. Estos resultados no explican por sí solos la dificultad.':'El tutor probó apoyos distintos y solicitó intervención presencial.'}</p><div class="table-wrap"><table><thead><tr><th>Actividad</th><th>Registro</th><th>Apoyos utilizados</th></tr></thead><tbody><tr><td>10 nov · Fracciones<br>Un tercio de 90 minutos</td><td>Respondió 45; luego pidió ayuda.</td><td>Pista verbal y barra visual del partido.</td></tr><tr><td>9 nov · Repartir goles<br>Tres cuartos de 12</td><td>Necesitó pasos guiados.</td><td>Grupos visuales y descomposición.</td></tr><tr><td>8 nov · Partes iguales</td><td>Completó con acompañamiento.</td><td>Objetos y explicación del tutor.</td></tr></tbody></table></div><div class="callout">Estos registros no constituyen un diagnóstico ni una comparación con otros alumnos.</div></section>`}
function history(){const notes=state.notes.filter(n=>n.student===student);return `<section class="card"><h2>Historial de miradas e intervenciones</h2><div class="timeline">${notes.map(n=>`<article class="event"><span class="tag blue">Docente · Clara López</span><p class="small muted">${esc(new Date(n.date).toLocaleString('es-AR'))}</p><h3 style="margin-top:8px">${esc(n.action)}</h3><p class="note-text">${esc(n.text)}</p><p class="small muted">Contexto: ${esc(n.context)}<br>Seguimiento: ${esc(n.followup)}</p><p class="small muted">Evidencias asociadas: ${esc(n.evidence)}</p></article>`).join('')}${student==='tomi'&&state.review?'<article class="event"><span class="tag amber">Revisión de adaptación</span><h3 style="margin-top:8px">Solicitud de revisión registrada</h3><p class="muted">La discrepancia permanece abierta. El plan actual no se modificó.</p></article>':''}${student==='tomi'?'<article class="event"><span class="tag lilac">Alumno · 9 nov</span><p>Expresó que no le gusta la temática de fútbol durante una actividad.</p></article><article class="event"><span class="tag green">Familia · 2 nov</span><p>Compartió fútbol y autitos como intereses. Se conserva el aporte original.</p></article>':'<article class="event"><span class="tag">Miseño · 10 nov</span><p>Se abrió la ficha con registros de su actividad escolar.</p></article>'}</div></section>`}
function detailLegacy(){const p=pupil(),isT=student==='tomi',isJ=student==='joaquin';let content=tab==='history'?history():tab==='activities'?activities():isT?sourcePanel():isJ?activities():`<section class="card"><h2>Su actividad actual</h2><p style="margin-top:15px">${p.activity}</p><div class="callout">${p.id==='mateo'?'Sin nuevos registros. La lectura de la pulsera no está disponible; no se infiere su estado ni el acompañamiento familiar.':'No hay una situación pendiente de revisión.'}</div><h3 style="margin-top:24px">Contexto de la familia</h3><p class="muted" style="margin-top:8px">Sin nuevos aportes familiares.</p></section>`;return `<div class="breadcrumb"><button class="link" data-page="group">Mi grupo</button><span class="muted">/</span>${p.name}</div>`+title(isT?'Entender lo que le pasa a Tomi':`Una mirada a ${p.name}`,isT?'Dificultad persistente · Revisar la adaptación de sus actividades.':p.activity,`<button class="btn" data-action="note">Registrar intervención</button>`)+`<div class="tabs" role="tablist" aria-label="Detalle del alumno">${[['activities','Actividades'],['evidence','Contexto y fuentes'],['interventions','Intervenciones']].map(([id,t])=>`<button role="tab" id="tab-${id}" aria-controls="detail-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}">${t}</button>`).join('')}</div><div class="grid"><div id="detail-panel" role="tabpanel" aria-labelledby="tab-${tab}">${content}</div><aside class="stack"><section class="card"><div class="split">${avatar(p)}<div><h3>${p.name}</h3><p class="small muted">Grupo A · Primaria</p></div></div><div class="status-grid"><div><strong class="small">${isT?'Discrepancia':'Situación'}</strong><span class="tag amber">${status(p)}</span></div><div><strong class="small">Intervención docente</strong><span class="muted small">${state.notes.some(n=>n.student===student)?'Registrada · Ver historial':'Sin registrar'}</span></div><div><strong class="small">Aprendizaje</strong><span class="muted small">${isT||isJ?'Dificultad en seguimiento':'Actividad en seguimiento'}</span></div></div>${isT?`<button class="btn secondary" data-action="start" ${state.started||state.review?'disabled':''}>${state.review?'Discrepancia en revisión':state.started?'Situación en atención':'Comenzar atención'}</button><div class="actions"><button class="btn" data-action="review" ${state.review?'disabled':''}>${state.review?'Revisión registrada':'Solicitar revisión'}</button></div><p class="small muted" style="margin-top:14px">La solicitud queda registrada. El plan permanece sin cambios.</p>`:isJ?'<p class="small muted">Registrá el acompañamiento antes de marcar la intervención como realizada.</p>':'<p class="small muted">Podés sumar una observación aunque no haya una alerta.</p>'}</section><section class="card glass"><h3>Intervención docente</h3><p class="muted small" style="margin-top:12px">Conversá con el alumno y contrastá lo que ves con los registros. Atender la situación no implica dar la dificultad por resuelta.</p></section></aside></div>`}
function pathsLegacy(){return title('Recorridos de aprendizaje','Temas, apoyos y cambios del plan, con contexto individual.')+`<div class="toolbar"><label for="path-student" style="margin:0">Alumno</label><select id="path-student">${pupils.map(p=>`<option value="${p.id}" ${p.id===student?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="grid"><section class="card"><div class="row"><h2>El recorrido de ${pupil().name}</h2><span class="tag">Vista por temas</span></div><p class="muted small" style="margin-top:9px">Los indicadores representan el avance dentro del tema.</p>${[['Matemática','Fracciones','Apoyo visual y pasos guiados',60],['Lengua','Comprensión de cuentos','Lectura acompañada',40],['Ciencias','Las plantas','Proyecto grupal de huerta',50],['Historia','La colonia','Exploración guiada',35],['Música','Flauta','En pausa en el plan',25]].map(([name,topic,desc,n])=>`<article class="subject"><div class="avatar" style="background:${name==='Música'?'#e9eceb':'#e8edf7'}">${name==='Matemática'?'½':name==='Ciencias'?'✿':name[0]}</div><div><h3>${name} · ${topic}</h3><p class="small muted">${desc}</p></div><div class="track"><span class="small muted">${name==='Música'?'En pausa':n+'% del tema'}</span><div class="bar" role="progressbar" aria-label="Avance en ${name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><i style="width:${n}%"></i></div></div></article>`).join('')}</section><aside class="stack"><section class="card alert"><span class="tag amber">Cambio del plan</span><h2 style="margin-top:15px">Más bloques de Matemática</h2><p class="muted" style="margin-top:12px">El plan suma dos bloques semanales y deja Música en pausa.</p><button class="btn secondary" data-action="plan" style="margin-top:20px">Consultar el cambio</button></section><section class="card"><h3>Lo que podés hacer</h3><p class="muted small" style="margin-top:12px">Consultar el recorrido y dejar una revisión registrada. La edición directa del plan sigue pendiente de definición.</p></section></aside></div>`}

function render(focus=false){if(page==='detail'||page==='situations')page='paths';if(page==='students')page='group';document.body.classList.toggle('launch-mode',page==='launch');nav();$('#main').innerHTML=({launch,group,paths,projects}[page])();if(page==='paths'){const c=$('.pupil-carousel');if(c){c.scrollLeft=carouselPosition;c.onscroll=()=>{carouselPosition=c.scrollLeft}}}if(page==='paths'&&$('#situation-filter'))$('#situation-filter').value=situationFilter;if(focus){$('#page-title').focus();window.scrollTo(0,0)}}

function modal(title,body){$('#dialog').innerHTML=`<div class="row"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="Cerrar">×</button></div>${body}`;$('#dialog').showModal()}
function note(){const p=pupil();modal(`Intervención · ${p.name}`,`<p class="muted" style="margin-top:12px">Registrá qué observaste y cómo acompañaste la situación.</p><form id="note-form"><label for="observation">Tu observación</label><textarea id="observation" required maxlength="2500" aria-describedby="note-error" placeholder="Por ejemplo: conversamos sobre sus intereses. Prefiere problemas con plantas y animales."></textarea><div id="note-error" class="error" role="alert"></div><label for="context">Contexto</label><select id="context"><option>Conversación presencial con el alumno</option><option>Observación durante la actividad</option><option>Conversación con la familia</option><option>Actividad grupal</option></select><label for="action">Acción realizada</label><select id="action"><option>Conversé con el alumno</option><option>Acompañé el ejercicio presencialmente</option><option>Contrasté los registros disponibles</option><option>Observé la actividad grupal</option></select><label for="followup">Seguimiento</label><select id="followup"><option>Continuar observando</option><option>Revisar adaptación con el equipo pedagógico</option><option>Retomar conversación con la familia</option></select><div class="callout">Evidencias asociadas: ${student==='tomi'?'aporte familiar del 2 nov, declaración del alumno del 9 nov y actividades del 8 al 10 nov.':'registros de actividad del alumno.'}</div><label class="check"><input type="checkbox" id="attended" checked><span>Registrar la intervención como realizada. La dificultad continúa en seguimiento.</span></label><p class="small muted">No modifica el plan ni resuelve automáticamente una discrepancia.</p><div class="actions"><button class="btn" type="submit">Guardar intervención</button><button class="btn ghost" type="button" data-action="close">Cancelar</button></div></form>`)}
const actions={close:()=>$('#dialog').close(),note,start:()=>{state.started=true;persist();render();toast('Situación en atención. Los registros originales se conservan.')},review:()=>modal('Revisar la adaptación de Tomi',`<p style="margin-top:18px">Se registrará una solicitud para contrastar los intereses utilizados y revisar la propuesta de actividades.</p><div class="callout amber">La discrepancia quedará “En revisión”. El plan actual permanece igual.</div><p class="muted small" style="margin-top:15px">Responsable y plazo de resolución: pendientes de asignación.</p><div class="actions"><button class="btn" data-action="confirm-review">Registrar solicitud</button><button class="btn ghost" data-action="close">Volver</button></div>`),'confirm-review':()=>{state.review=true;state.started=true;const ok=persist();$('#dialog').close();render();if(ok)toast('Revisión registrada. El plan no cambió.')},plan:()=>modal('Revisión del cambio de plan',`<p style="margin-top:18px">${pupil().name} · Matemática suma dos bloques y Música queda en pausa.</p><div class="callout"><strong>Explicación de Miseño</strong><p>“Se eligió el mejor camino según cómo aprende el alumno”.</p></div><p class="muted" style="margin-top:15px">No se detalla qué datos justificaron este cambio. La autoridad para aprobar o suspenderlo sigue pendiente de definición.</p><div class="actions"><button class="btn" data-action="plan-review" ${state.planReview?'disabled':''}>${state.planReview?'Solicitud registrada':'Registrar pedido de revisión'}</button></div><p class="small muted" style="margin-top:15px">La solicitud no modifica el recorrido.</p>`),'plan-review':()=>{state.planReview=true;const ok=persist();$('#dialog').close();if(ok)toast('Pedido de revisión del plan guardado.')},project:()=>modal('Organizar la huerta',`<p style="margin-top:18px">Grupo propuesto: Joaquín, Sofía y Bruno.</p><ul><li>Reunir al grupo y preparar tierra, semillas y recipientes.</li><li>Conversar cómo se repartirán las tareas.</li><li>Observar la participación y los acuerdos entre compañeros.</li></ul><p class="muted">Cambiar integrantes requiere definir primero la autoridad docente sobre los agrupamientos.</p><div class="actions"><button class="btn" data-action="project-note">Registrar observación de Joaquín</button></div>`),'project-note':()=>{$('#dialog').close();student='joaquin';note();$('#context').value='Actividad grupal';$('#action').value='Observé la actividad grupal'},reset:()=>modal('Reiniciar el ejemplo',`<p style="margin-top:18px">Se eliminarán únicamente las intervenciones y solicitudes guardadas por este prototipo de Miseño en este navegador.</p><div class="actions"><button class="btn" data-action="confirm-reset">Reiniciar demo</button><button class="btn ghost" data-action="close">Cancelar</button></div>`),'confirm-reset':()=>{state=initial();persist();$('#dialog').close();page='group';query='';groupFilter='all';situationFilter='all';render(true);toast('Demo reiniciada.') }};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render(true)}else if(b.dataset.student){openPupil(b.dataset.student)}else if(b.dataset.tab){selectJourneyTab(b.dataset.tab)}else if(b.dataset.action&&actions[b.dataset.action])actions[b.dataset.action]()});
document.addEventListener('change',e=>{if(e.target.id==='group-filter'){groupFilter=e.target.value;render()}if(e.target.id==='situation-filter'){situationFilter=e.target.value;render()}if(e.target.id==='path-student'){student=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=['activities','evidence','interventions'],i=ids.indexOf(tab);tab=e.key==='Home'?ids[0]:e.key==='End'?ids[2]:ids[(i+(e.key==='ArrowRight'?1:2))%3];selectJourneyTab(tab)});
document.addEventListener('submit',e=>{if(e.target.id!=='note-form')return;e.preventDefault();const text=$('#observation').value.trim();if(!text){$('#note-error').textContent='Escribí qué observaste antes de guardar.';$('#observation').focus();return}const attended=$('#attended').checked;state.notes.unshift({student,text,context:$('#context').value,action:$('#action').value,followup:$('#followup').value,date:new Date().toISOString(),attended,evidence:student==='tomi'?'Familia 2 nov; alumno 9 nov; actividades 8–10 nov':'Registros de actividad del alumno'});if(student==='joaquin'&&attended)state.academic=true;if(student==='tomi')state.started=true;const ok=persist();$('#dialog').close();page='paths';tab='interventions';render(true);if(ok)toast('Intervención guardada en el historial. La dificultad sigue en seguimiento.')});

function launch(){return `<div class="launch-screen"><div class="brand"><span class="orb" aria-hidden="true"></span>Miseño</div><h1 id="page-title" tabindex="-1">Espacio docente</h1><div class="launch-options">${[['group','Grupo','Actividades del grupo'],['paths','Recorridos','Situaciones, fuentes e historial'],['projects','Proyectos','Trabajo grupal']].map(([id,t,d])=>`<button data-page="${id}"><span class="launch-icon">${icon(id==='students'?'group':id)}</span><strong>${t}</strong><span>${d}</span></button>`).join('')}</div></div>`}

function recommendations(){const p=pupil();return `<section class="card" style="margin-top:22px"><div class="row"><h2>Recomendaciones de la IA</h2><span class="tag lilac">Miseño · Propuesta</span></div><p style="margin-top:14px">${student==='tomi'?'Contrastar los intereses con Tomi y probar una actividad con otra temática antes de atribuir una causa a las dificultades.':student==='joaquin'?'Retomar el ejercicio con acompañamiento presencial y registrar qué parte necesita otra explicación.':'Registrar observaciones de la actividad actual antes de proponer nuevos ajustes.'}</p><div class="callout">${student==='tomi'?'Fundamento: diferencia entre la declaración familiar y la expresión del alumno; necesidad de apoyo en las actividades.':'Fundamento: registros de la actividad actual.'} La propuesta requiere revisión docente; no se aplica automáticamente.</div><div class="actions"><button class="btn secondary" data-action="edit-adaptation">Proponer ajuste</button></div>${(state.adjustments||[]).filter(a=>a.student===student).map(a=>`<div class="callout"><strong>Propuesta docente · ${esc(a.theme)}</strong><p>${esc(a.support)}</p><span>Registrada · Plan sin modificar</span></div>`).join('')}</section>`}

actions['close-profile']=()=>{const id=selectedProfile;selectedProfile=null;render();const trigger=document.querySelector('[data-profile="'+id+'"]');if(trigger)trigger.focus()};
actions['edit-adaptation']=()=>modal('Proponer ajuste · '+pupil().name,`<p class="muted" style="margin-top:15px">Registrá una propuesta para este alumno. No se aplica al plan automáticamente.</p><form id="adjust-form"><label for="adjust-theme">Temática a explorar</label><select id="adjust-theme"><option>Plantas y animales</option><option>Situaciones cotidianas</option><option>Fútbol</option><option>Consultar intereses con el alumno</option></select><label for="adjust-support">Apoyo y motivo del ajuste</label><textarea id="adjust-support" required maxlength="1500" placeholder="Qué cambiarías y qué observación fundamenta la propuesta"></textarea><div id="adjust-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="submit">Guardar propuesta</button><button class="btn ghost" type="button" data-action="close">Cancelar</button></div></form>`);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.profile){e.stopImmediatePropagation();student=b.dataset.profile;selectedProfile=b.dataset.profile;page='group';render();$('#profile-heading').focus()}if(b.dataset.history){e.stopImmediatePropagation();student=b.dataset.history;page='paths';tab='interventions';render(true)}if(b.dataset.carousel){e.stopImmediatePropagation();const c=$('.pupil-carousel');if(c)c.scrollBy({left:Number(b.dataset.carousel)*260,behavior:'smooth'})}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='adjust-form')return;e.preventDefault();const support=$('#adjust-support').value.trim();if(!support){$('#adjust-error').textContent='Escribí el motivo del ajuste.';return}state.adjustments=state.adjustments||[];state.adjustments.unshift({student,theme:$('#adjust-theme').value,support,date:new Date().toISOString()});const ok=persist();$('#dialog').close();render();if(ok)toast('Propuesta guardada. El plan no se modificó.')});

