let insightTab='family',carouselPosition=0;
function compactInsights(){const d=learningData[student];return `<aside class="insight-capsule card"><div class="insight-pills" role="group" aria-label="Aportes y recomendaciones"><button data-insight="family" aria-pressed="${insightTab==='family'}">Familia</button><button data-insight="ai" aria-pressed="${insightTab==='ai'}">${icon('paths')} IA</button></div>${insightTab==='family'?`<div class="capsule-content"><span class="tag green">Familia · ${d.date}</span><blockquote>${esc(d.family)}</blockquote><p class="small muted">Aporte conservado con su fuente y fecha.</p><div class="capsule-divider"></div><span class="tag lilac">Alumno · Declaración explícita</span><blockquote>${esc(d.child)}</blockquote><p class="small muted">${esc(d.context)}</p></div>`:`<div class="capsule-content"><span class="tag lilac">Interpretación de Miseño</span><p style="margin-top:12px">${esc(d.finding)}</p><h3 style="margin-top:22px">Recomendación</h3><p style="margin-top:10px">${esc(d.recommend)}</p>${recommendationActions()}<div class="capsule-divider"></div><h3>Conversar con Miseño</h3><p class="small muted" style="margin-top:6px">Conversación simulada sobre ${pupil().name}.</p><div class="chat-log" role="log" aria-label="Conversación sobre ${pupil().name}">${(state.chats?.[student]||[]).map(m=>`<div class="chat-message ${m.role}"><strong>${m.role==='user'?'Vos':'Miseño'}</strong><p>${esc(m.text)}</p></div>`).join('')||'<p class="small muted">Consultá los registros o pedí un cambio en la propuesta.</p>'}</div><div class="chat-suggestions"><button data-prompt="¿Qué le está costando?">¿Qué le cuesta?</button><button data-prompt="¿Por qué recomendás esta actividad?">¿Por qué?</button><button data-prompt="Quiero cambiar la temática">Pedir un cambio</button></div><form id="chat-form"><label for="chat-input" class="small">Mensaje para Miseño</label><textarea id="chat-input" maxlength="1500" rows="2" required placeholder="Preguntá por el alumno o pedí un cambio…"></textarea><div id="chat-error" class="error" role="alert"></div><button class="btn" style="margin-top:10px" type="submit">Enviar ${icon('paths')}</button></form>${(state.chatRequests||[]).filter(r=>r.student===student).map(r=>`<div class="callout"><strong>Pedido de cambio registrado</strong><p>${esc(r.text)}</p><span class="small">Pendiente de revisión · Plan sin modificar</span></div>`).join('')}</div>`}</aside>`}
function legacyStudentRecords(){const d=learningData[student];if(tab==='history')return history()+`<section class="card" style="margin-top:22px"><h2>Observaciones anteriores</h2><div class="timeline">${d.observations.map(([date,text])=>`<article class="event"><span class="small muted">${date}</span><p>${esc(text)}</p></article>`).join('')}</div></section>`;if(tab==='activities')return `<section class="card"><h2>Actividades y apoyos utilizados</h2><div class="table-wrap"><table><thead><tr><th>Fecha y actividad</th><th>Registro</th><th>Apoyo</th></tr></thead><tbody>${d.sessions.map(([date,activity,result,support])=>`<tr><td>${date}<br>${esc(activity)}</td><td>${esc(result)}</td><td>${esc(support)}</td></tr>`).join('')}</tbody></table></div></section>`;return student==='tomi'?sourcePanel():`<section class="card"><div class="row"><h2>Contexto de ${pupil().name}</h2><span class="tag">${status(pupil())}</span></div><div class="callout"><strong>Actividad actual</strong><p>${pupil().activity}</p></div><h3 style="margin-top:24px">Lo que expresó el alumno</h3><p style="margin-top:12px">${esc(d.child)}</p><p class="small muted">${esc(d.context)}</p><h3 style="margin-top:24px">Últimas observaciones</h3><div class="timeline">${d.observations.map(([date,text])=>`<article class="event"><span class="small muted">${date}</span><p>${esc(text)}</p></article>`).join('')}</div></section>`}
function interventionRecords(){const d=learningData[student],notes=state.notes.filter(n=>n.student===student);return `<section class="card"><div class="row"><div><h2>Intervenciones docentes</h2><p class="small muted" style="margin-top:8px">${pupil().name} · Acciones y seguimiento</p></div><button class="btn" data-action="note">Nueva intervención</button></div><div class="timeline">${notes.map(n=>`<article class="event"><span class="tag blue">Docente · Clara López</span><p class="small muted">${esc(new Date(n.date).toLocaleString('es-AR'))}</p><h3 style="margin-top:10px">${esc(n.action)}</h3><p>${esc(n.text)}</p><p class="small muted">Contexto: ${esc(n.context)}<br>Seguimiento: ${esc(n.followup)}</p><span class="tag ${n.attended?'green':''}">${n.attended?'Intervención realizada':'Registro de observación'}</span></article>`).join('')}${d.observations.filter(([date])=>date.includes('Docente')).map(([date,text])=>`<article class="event"><span class="small muted">${date} · Clara López</span><h3 style="margin-top:10px">Acompañamiento en el aula</h3><p>${esc(text)}</p><p class="small muted">Seguimiento: retomar en la próxima actividad.</p><span class="tag green">Intervención realizada</span></article>`).join('')}</div></section>`}
function studentRecords(){if(tab==='activities')return activitiesWithRecords();if(tab==='interventions')return interventionRecords();if(tab==='activities')return legacyStudentRecords()+`<section class="card embedded-history"><h2>Seguimiento de actividades</h2><div class="timeline">${learningData[student].sessions.map(([date,name,result,support])=>`<article class="event"><span class="small muted">${date} · ${esc(name)}</span><p>${esc(result)}</p><p class="small muted">Apoyo utilizado: ${esc(support)}</p></article>`).join('')}</div></section>`;return legacyStudentRecords()+`<section class="card embedded-history"><div class="row"><h2>Registro de contexto y decisiones</h2>${student==='tomi'?`<button class="btn secondary" data-action="review" ${state.review?'disabled':''}>${state.review?'En revisión':'Solicitar revisión'}</button>`:''}</div><div class="timeline">${learningData[student].observations.map(([date,text])=>`<article class="event"><span class="small muted">${esc(date)}</span><p>${esc(text)}</p></article>`).join('')}${student==='tomi'&&state.review?'<article class="event"><span class="tag amber">Discrepancia en revisión</span><p>Solicitud registrada. El plan permanece sin cambios.</p></article>':''}${(state.chatRequests||[]).filter(r=>r.student===student).map(r=>`<article class="event"><span class="tag blue">Pedido docente vía Miseño</span><p>${esc(r.text)}</p><p class="small muted">${esc(new Date(r.date).toLocaleString('es-AR'))} · Pendiente de revisión</p></article>`).join('')}</div></section>`}

function paths(){return `<h1 id="page-title" tabindex="-1" class="sr-only">Recorridos</h1><div class="carousel-row"><button class="btn ghost" data-carousel="-1" aria-label="Desplazar alumnos hacia la izquierda">←</button><div class="pupil-carousel" tabindex="0" aria-label="Carrusel de alumnos">${pupils.map(p=>`<button data-student="${p.id}" aria-pressed="${student===p.id}" class="pupil-choice">${avatar(p)}<span>${p.name}</span></button>`).join('')}</div><button class="btn ghost" data-carousel="1" aria-label="Desplazar alumnos hacia la derecha">→</button></div><div class="journey-layout"><div><div class="tabs" role="tablist" aria-label="Detalle del alumno">${[['activities','Actividades'],['evidence','Contexto y fuentes'],['interventions','Intervenciones']].map(([id,t])=>`<button role="tab" id="tab-${id}" aria-controls="detail-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}">${t}</button>`).join('')}</div><div id="detail-panel" role="tabpanel" aria-labelledby="tab-${tab}">${studentRecords()}</div>${(state.adjustments||[]).filter(a=>a.student===student).map(a=>`<div class="callout"><strong>Propuesta docente · ${esc(a.theme)}</strong><p>${esc(a.support)}</p><span>Registrada · Plan sin modificar</span></div>`).join('')}</div>${compactInsights()}</div>`}
function sendChat(text){text=text.trim();if(!text)return false;const d=learningData[student], normalized=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let answer;
if(/cambi|modific|ajust|reemplaz|agreg|quita|mas tiempo|menos tiempo|aument|reduc|prefier|usar |usemos|quiero que/.test(normalized)){state.chatRequests=state.chatRequests||[];state.chatRequests.unshift({student,text,date:new Date().toISOString()});answer=`Registré tu pedido para ${pupil().name}: “${text}”. La propuesta actual es trabajar ${d.theme.toLowerCase()} con ${d.support.toLowerCase()}. Podemos usar este pedido para preparar una revisión; el plan todavía no se modificó.`}
else if(/famil|casa|padre|madre/.test(normalized))answer=`La familia informó el ${d.date}: ${d.family} El alumno expresó: ${d.child} Conviene considerar ambos contextos antes de decidir un ajuste.`;
else if(/por que|recom|actividad|ayud|apoyo/.test(normalized))answer=`Recomiendo: ${d.recommend} Me baso en estos registros: ${d.finding} Es una propuesta para revisar con tu observación docente.`;
else if(/historial|avan|progres|ultim/.test(normalized))answer=`En los últimos registros: ${d.sessions.map(s=>s[0]+': '+s[2]).join('; ')}. La observación docente más reciente dice: ${d.observations[0][1]}`;
else if(/cuesta|dific|como|que|situacion/.test(normalized))answer=`Sobre ${pupil().name}: ${d.finding} Propongo ${d.recommend.charAt(0).toLowerCase()+d.recommend.slice(1)}`;
else answer=`Puedo consultar los registros de ${pupil().name}, explicar la recomendación o registrar un pedido de cambio. Para esta consulta no tengo más información que las actividades, las observaciones y los aportes que aparecen en su ficha.`;
state.chats=state.chats||{};state.chats[student]=state.chats[student]||[];state.chats[student].push({role:'user',text},{role:'assistant',text:answer});persist();insightTab='ai';render();const log=$('.chat-log');if(log)log.scrollTop=log.scrollHeight;return true;}
document.addEventListener('wheel',e=>{const c=e.target.closest('.pupil-carousel');if(!c||e.ctrlKey)return;const delta=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;const pixels=delta*(e.deltaMode===1?20:e.deltaMode===2?c.clientWidth:1);const canMove=pixels<0?c.scrollLeft>0:c.scrollLeft<c.scrollWidth-c.clientWidth-1;if(canMove){e.preventDefault();c.scrollLeft+=pixels;carouselPosition=c.scrollLeft}},{passive:false});
document.addEventListener('keydown',e=>{if(!e.target.classList?.contains('pupil-carousel'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();e.target.scrollBy({left:e.key==='ArrowRight'?220:-220,behavior:'smooth'})}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.insight){selectInsight(b.dataset.insight)}if(b.dataset.prompt)sendChat(b.dataset.prompt)});
document.addEventListener('submit',e=>{if(e.target.id!=='chat-form')return;e.preventDefault();if(!sendChat($('#chat-input').value))$('#chat-error').textContent='Escribí una consulta o un pedido de cambio.'});


