addedPupils.forEach(([id,name,subject,activity,theme,family,child,finding,recommend],i)=>{pupils.push({id,name,short:name,initial:name[0],subject,activity,color:['#eee9fa','#e0f1e8','#f7e8df','#e2eff4'][i%4],status:i===1||i===5?'Necesita acompañamiento':'Actividad en curso'});learningData[id]={family,date:'9 nov',child,context:'10 nov · Conversación con el tutor',finding,recommend,theme,support:['Tarjetas visuales y exploración guiada','Objetos manipulables y registro escrito','Comparación de imágenes y preguntas breves'][i%3],sessions:[['10 nov',activity,'Completó la primera consigna con apoyo','Exploración guiada'],['9 nov',theme+' · Práctica','Compartió una explicación oral','Ejemplo visual'],['6 nov',theme+' · Inicio','Identificó conocimientos previos','Conversación con el tutor']],observations:[['10 nov · Docente',finding+' Se acompañó la actividad y se acordó retomar la práctica.'],['9 nov · Familia',family]]}});


// Update only the selected panel: keep navigation, carousel and sidebar mounted.
function selectJourneyTab(next){if(!['activities','evidence','interventions'].includes(next))return;tab=next;const panel=$('#detail-panel');if(!panel)return;panel.innerHTML=studentRecords();panel.setAttribute('aria-labelledby','tab-'+tab);for(const id of ['activities','evidence','interventions']){const button=$('#tab-'+id);button.setAttribute('aria-selected',String(id===tab));button.tabIndex=id===tab?0:-1}$('#tab-'+tab).focus()}
function selectInsight(next){insightTab=next;const capsule=$('.insight-capsule');if(!capsule)return;const template=document.createElement('template');template.innerHTML=compactInsights();const nextCapsule=template.content.firstElementChild;capsule.querySelector('.capsule-content').replaceWith(nextCapsule.querySelector('.capsule-content'));capsule.querySelectorAll('[data-insight]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.insight===next)));capsule.querySelector('[data-insight="'+next+'"]').focus()}

function activityProposal(id=student){const d=learningData[id];return id==='joaquin'?{title:'Repartimos piezas en partes iguales',objective:'Reconocer que el denominador indica en cuántas partes iguales se divide el entero.',instruction:'Armá un entero con 12 piezas. Dividilo en 3 grupos iguales. Señalá un tercio y explicá qué indica el 3. Después repartí las mismas piezas en 4 grupos y compará un tercio con un cuarto.',duration:12,support:'12 piezas manipulables, barra de fracciones y preguntas guiadas.',reason:'En dos registros Joaquín confundió numerador y denominador. Las respuestas mejoraron al utilizar piezas y apoyos visuales.',slot:'Próximo bloque de Matemática'}:{title:'Práctica guiada · '+d.theme,objective:'Retomar el aspecto observado en '+pupil(id).subject+' con apoyo específico.',instruction:d.recommend,duration:15,support:d.support,reason:d.finding,slot:'Próximo bloque de '+pupil(id).subject}}
function proposedActivityCard(){const proposal=activityProposal(),accepted=state.nextActivities?.[student];return `<section class="card next-activity"><div class="row"><div><span class="tag ${accepted?'green':'lilac'}">${accepted?'Próxima actividad':'Propuesta de Miseño'}</span><h2 style="margin-top:12px">${esc(accepted?accepted.title:proposal.title)}</h2></div><span class="small muted">${proposal.duration} min</span></div><p class="muted" style="margin-top:12px">${esc(proposal.objective)}</p>${accepted?`<p class="small muted" style="margin-top:12px">${esc(accepted.slot)} · Aceptada por Clara López<br>${esc(new Date(accepted.acceptedAt).toLocaleString('es-AR'))}</p>`:'<p class="small muted" style="margin-top:12px">Todavía no forma parte de la secuencia del alumno.</p>'}<div class="actions"><button class="btn secondary" data-action="preview-activity">${accepted?'Revisar próxima actividad':'Ver actividad sugerida'}</button></div></section>`}
function recommendationActions(){return `<div class="actions"><button class="btn" data-action="preview-activity">${state.nextActivities?.[student]?'Ver próxima actividad':'Ver actividad sugerida'}</button><button class="btn secondary" data-action="check-activities">Revisar actividades</button></div><p class="small muted" style="margin-top:10px">${state.nextActivities?.[student]?'Aceptada por Clara López para el próximo bloque.':'Propuesta pendiente de decisión docente.'}</p>`}
function activitiesWithRecords(){const d=learningData[student],reviewed=state.reviewedRecords?.[student]||[];return proposedActivityCard()+`<section class="card" style="margin-top:22px"><h2>Actividades realizadas</h2><p class="small muted" style="margin-top:10px">Consultá las respuestas y los apoyos antes de decidir la próxima práctica.</p><div class="table-wrap"><table><thead><tr><th>Fecha y actividad</th><th>Resultado registrado</th><th>Apoyos</th><th>Detalle</th></tr></thead><tbody>${d.sessions.map(([date,name,result,support],i)=>`<tr><td>${date}<br>${esc(name)}</td><td>${esc(result)}</td><td>${esc(support)}</td><td><button class="link" data-record="${i}">Ver registro</button>${reviewed.includes(i)?'<span class="tag green">Consultado</span>':''}</td></tr>`).join('')}</tbody></table></div></section><section class="card embedded-history"><h2>Seguimiento de actividades</h2><div class="timeline">${d.sessions.map(([date,name,result,support])=>`<article class="event"><span class="small muted">${date} · ${esc(name)}</span><p>${esc(result)}</p><p class="small muted">Apoyo: ${esc(support)}</p></article>`).join('')}</div></section>`}
function showActivityRecord(index){const row=learningData[student].sessions[index];if(!row)return;state.reviewedRecords=state.reviewedRecords||{};state.reviewedRecords[student]=state.reviewedRecords[student]||[];if(!state.reviewedRecords[student].includes(index))state.reviewedRecords[student].push(index);persist();selectJourneyTab('activities');let details;
if(student==='joaquin'&&index===0)details='<h3 style="margin-top:20px">Consigna presentada</h3><p>Hay 12 piezas divididas en 3 grupos iguales. ¿Qué indica el 3 de la fracción 1/3?</p><h3 style="margin-top:20px">Respuesta del alumno</h3><p>“Las piezas que me quedo”. Confundió la cantidad de grupos con la parte seleccionada.</p><h3 style="margin-top:20px">Después del apoyo</h3><p>Al repartir las piezas presencialmente, reconoció los tres grupos. Todavía necesitó una pregunta guiada para explicar el denominador.</p>';
else if(student==='joaquin'&&index===2)details='<h3 style="margin-top:20px">Consigna presentada</h3><p>Señalá una mitad en una barra dividida en dos partes iguales y explicá qué representa el 2.</p><h3 style="margin-top:20px">Respuesta del alumno</h3><p>Señaló una mitad, pero explicó el 2 como “lo que tomo”.</p><h3 style="margin-top:20px">Después del apoyo</h3><p>Identificó las dos partes al señalarlas. Necesitó acompañamiento para distinguirlas de la parte elegida.</p>';
else details=`<h3 style="margin-top:20px">Registro de la actividad</h3><p>${esc(row[2])}</p><p class="muted" style="margin-top:10px">${esc(learningData[student].finding)}</p>`;
modal('Registro · '+pupil().name,`<p class="small muted" style="margin-top:12px">${esc(row[0])} · ${esc(row[1])}</p>${details}<div class="callout"><strong>Apoyo utilizado</strong><p>${esc(row[3])}</p></div><div class="actions"><button class="btn secondary" data-action="close">Volver a las actividades</button><button class="btn" data-action="record-to-proposal">Ver sugerencia de la IA</button></div>`)}
actions['record-to-proposal']=()=>{$('#dialog').close();actions['preview-activity']()};
actions['check-activities']=()=>{selectJourneyTab('activities');toast('Revisá los registros de actividades realizadas.')};
actions['preview-activity']=()=>{const p=activityProposal(),accepted=state.nextActivities?.[student],count=state.reviewedRecords?.[student]?.length||0;modal(p.title,`<span class="tag ${accepted?'green':'lilac'}" style="margin-top:15px">${accepted?'Aceptada por Clara López':'Sugerencia de Miseño'}</span><h3 style="margin-top:20px">Objetivo</h3><p>${esc(p.objective)}</p><h3 style="margin-top:20px">Consigna</h3><p>${esc(p.instruction)}</p><div class="callout"><strong>${p.duration} minutos · ${esc(p.slot)}</strong><p>Apoyos: ${esc(p.support)}</p></div><h3 style="margin-top:20px">Por qué se propone</h3><p>${esc(p.reason)}</p>${accepted?`<p class="callout">Aceptada el ${esc(new Date(accepted.acceptedAt).toLocaleString('es-AR'))}. Quedó programada como próxima actividad, sin modificar las actividades ya realizadas.</p><div class="actions"><button class="btn secondary" data-action="close">Volver</button></div>`:`<p class="small muted" style="margin-top:15px">${count?count+' registro(s) consultado(s) en Actividades.':'Aún no consultaste el detalle de las actividades.'}</p><form id="accept-activity-form"><label class="check"><input id="activity-evidence-confirm" type="checkbox" required><span>Contrasté la sugerencia con las actividades y considero adecuada esta práctica.</span></label><div id="accept-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="submit">Aceptar como próxima actividad</button><button class="btn secondary" type="button" data-action="preview-to-records">Revisar actividades</button><button class="btn ghost" type="button" data-action="preview-to-adjust">Pedir un ajuste</button></div><p class="small muted" style="margin-top:12px">Al aceptar, reemplaza la próxima propuesta de práctica de esta materia. Las demás actividades se conservan.</p></form>`}`)};
actions['preview-to-records']=()=>{$('#dialog').close();selectJourneyTab('activities')};
actions['preview-to-adjust']=()=>{$('#dialog').close();actions['edit-adaptation']()};
function acceptNextActivity(){if(state.nextActivities?.[student])return false;const p=activityProposal(),date=new Date().toISOString();state.nextActivities=state.nextActivities||{};state.nextActivities[student]={...p,acceptedAt:date,teacher:'Clara López'};state.notes.unshift({student,text:'Se contrastaron los registros de actividades y se aceptó la propuesta de Miseño “'+p.title+'” como próxima actividad. Objetivo: '+p.objective,context:'Revisión de actividades y recomendación de Miseño',action:'Aceptación de próxima actividad',followup:'Observar el resultado en el próximo bloque de '+pupil().subject,date,attended:true,evidence:(state.reviewedRecords?.[student]||[]).map(i=>learningData[student].sessions[i].slice(0,2).join(' · ')).join('; ')||'Revisión declarada por la docente'});const ok=persist();$('#dialog').close();tab='activities';page='paths';render();toast(ok?'Próxima actividad programada · Aceptada por Clara López.':'Actividad programada durante esta sesión; no se pudo guardar en el navegador.');return true}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&b.dataset.record!==undefined)showActivityRecord(Number(b.dataset.record))});
document.addEventListener('submit',e=>{if(e.target.id!=='accept-activity-form')return;e.preventDefault();if(!$('#activity-evidence-confirm').checked){$('#accept-error').textContent='Confirmá que contrastaste la sugerencia antes de aceptarla.';return}acceptNextActivity()});

// Project records are stored once; student histories reference the same event.
let projectId='huerta',projectTab='teams',selectedTeam='h1';
const projectDefinitions={huerta:{name:'Nuestra primera huerta',subject:'Ciencias',goal:'Observar las necesidades de las plantas, acordar tareas y registrar su crecimiento.',date:'Próxima sesión · 40 minutos',materials:'Semillas, tierra, recipientes, agua y hojas de registro.'},barrio:{name:'Un mapa de nuestro barrio',subject:'Historia y Matemática',goal:'Representar lugares y recorridos, comparar distancias y construir un mapa en equipo.',date:'Próxima sesión · 35 minutos',materials:'Plano base, fotografías, reglas y tarjetas de lugares.'}};
function ensureProjects(){if(!state.projectGroups)state.projectGroups={huerta:[{id:'h1',name:'Semillas',members:['joaquin','sofia','bruno','lucia'],criterion:'Continuidad del equipo de huerta, con un espacio de lectura y registro compartido.'},{id:'h2',name:'Riego',members:['tomi','benjamin','mateo','nicolas'],criterion:'Observación, construcción y medidas en una tarea concreta.'},{id:'h3',name:'Observación',members:['emma','valentina','isabella','felipe'],criterion:'Preguntas de exploración y registro de los pasos de la actividad.'},{id:'h4',name:'Registro',members:['catalina','santino','olivia','tomasp'],criterion:'Descripción, dibujo y organización del registro.'}],barrio:[{id:'b1',name:'Plazas',members:['joaquin','emma','santino','olivia'],criterion:'Explorar referencias y servicios del barrio.'},{id:'b2',name:'Recorridos',members:['tomi','bruno','nicolas','felipe'],criterion:'Combinar relatos, medidas e instrucciones de recorridos.'},{id:'b3',name:'Edificios',members:['sofia','benjamin','catalina','tomasp'],criterion:'Construcción, formas y descripción de lugares.'},{id:'b4',name:'Naturaleza',members:['mateo','lucia','valentina','isabella'],criterion:'Investigar espacios verdes y producir un registro compartido.'}]};if(!state.projectEvents)state.projectEvents=[];if(!state.projectIncidents)state.projectIncidents=[{id:'turnos',project:'huerta',title:'Desacuerdo sobre el reparto de tareas',studentIds:['sofia','bruno'],source:'Docente · Clara López',date:'10 nov · Registro de aula',description:'Sofía y Bruno quisieron usar el mismo material y no acordaron quién registraba el riego. La actividad se interrumpió para conversar.',status:'open',recommendation:'Escuchar ambas versiones, acordar turnos de uso de materiales y rotar los roles durante la próxima sesión.'},{id:'materiales',project:'barrio',title:'Materiales compartidos entre equipos',studentIds:['santino','nicolas'],source:'Docente · Clara López',date:'10 nov · Registro de aula',description:'Dos equipos pidieron la misma regla al mismo tiempo. No quedó acordado cómo compartir el material.',status:'followup',recommendation:'Reunir a los representantes de ambos equipos, acordar un orden de uso y verificarlo al cierre.'}];}
function projectTeams(){ensureProjects();return state.projectGroups[projectId]}
function chosenTeam(){const groups=projectTeams();return groups.find(t=>t.id===selectedTeam)||groups[0]}
function memberNames(ids){return ids.map(id=>pupil(id).name).join(', ')}
function projectEventCard(event){return `<article class="event"><div class="row"><span class="tag blue">Docente · Clara López</span><span class="small muted">${esc(new Date(event.date).toLocaleString('es-AR'))}</span></div><h3 style="margin-top:12px">${esc(event.type)}</h3><p>${esc(event.text)}</p><p class="small muted">${esc(projectDefinitions[event.project].name)} · ${esc(memberNames(event.studentIds))}</p><p class="small muted">Seguimiento: ${esc(event.followup)}</p>${event.incidentId?'<span class="tag">Intervención de convivencia</span>':''}</article>`}
function projectRoster(){return `<div class="project-roster">${projectTeams().map(team=>`<button class="team-select" data-team="${team.id}" aria-pressed="${chosenTeam().id===team.id}"><strong>${esc(team.name)}</strong><span class="small muted">${esc(memberNames(team.members))}</span></button>`).join('')}</div>`}
function projectNavigation(){return `<div class="tabs project-tabs" role="group" aria-label="Secciones del proyecto">${[['teams','Grupos'],['follow','Seguimiento'],['coexist','Convivencia']].map(([id,label])=>`<button data-project-tab="${id}" aria-pressed="${projectTab===id}">${label}</button>`).join('')}</div>`}
function groupProjectPanel(){const team=chosenTeam();const unassigned=pupils.filter(p=>!projectTeams().some(t=>t.members.includes(p.id)));return `<div class="project-columns"><aside class="card"><div class="row"><h2>Equipos</h2><button class="link" data-project-action="new-team">Crear grupo</button></div>${projectRoster()}${unassigned.length?`<div class="callout amber"><strong>Sin asignar</strong><p>${esc(memberNames(unassigned.map(p=>p.id)))}</p></div>`:''}</aside><div class="stack"><section class="card"><div class="row"><h2>${esc(team.name)}</h2><button class="btn secondary" data-project-action="edit-team">Editar integrantes</button></div><div class="project-member-cards">${team.members.map(id=>`<button class="student" data-student="${id}"><div class="split">${avatar(pupil(id))}<div><strong>${pupil(id).name}</strong><div class="small muted">Ver recorrido</div></div></div><p>${esc(learningData[id].theme)}</p></button>`).join('')}</div><h3 style="margin-top:22px">Criterio del agrupamiento</h3><p class="muted" style="margin-top:10px">${esc(team.criterion)}</p><div class="callout">Roles a rotar: materiales, observación, registro y puesta en común.</div></section><section class="card"><span class="tag lilac">Propuesta de Miseño</span><h2 style="margin-top:14px">Explorar otra organización</h2><p class="muted" style="margin-top:12px">Preparar equipos a partir de los intereses registrados y distribuir oportunidades de participación. Podés revisar la propuesta antes de confirmarla.</p><div class="actions"><button class="btn secondary" data-project-action="suggest">Pedir propuesta de grupos</button></div></section></div></div>`}
function followProjectPanel(){const team=chosenTeam(),events=state.projectEvents.filter(e=>e.project===projectId&&e.studentIds.some(id=>team.members.includes(id)));return `<div class="project-columns"><aside class="card"><h2>Seleccionar equipo</h2>${projectRoster()}</aside><section class="card"><div class="row"><h2>Seguimiento · ${esc(team.name)}</h2><button class="btn" data-project-action="observe">Registrar observación</button></div><p class="muted" style="margin-top:12px">${esc(memberNames(team.members))}</p><div class="project-checkpoints"><div><strong>Participación</strong><p class="small muted">Quién propone, escucha y toma la palabra.</p></div><div><strong>Organización</strong><p class="small muted">Acuerdos sobre roles y materiales.</p></div><div><strong>Aprendizaje</strong><p class="small muted">Qué se pudo hacer y dónde hizo falta apoyo.</p></div></div><div class="timeline">${events.length?events.map(projectEventCard).join(''):'<p class="empty">Todavía no hay observaciones registradas para este equipo.</p>'}</div></section></div>`}
const incidentLabels={open:'Pendiente de intervención',followup:'En seguimiento',resolved:'Cerrada por la docente'};
function coexistProjectPanel(){const incidents=state.projectIncidents.filter(i=>i.project===projectId);return `<section class="card"><div class="row"><div><h2>Convivencia en el proyecto</h2><p class="muted" style="margin-top:10px">Situaciones dentro de un equipo o entre equipos.</p></div><button class="btn" data-project-action="new-incident">Registrar situación</button></div><div class="incident-list">${incidents.map(i=>`<article class="incident-card"><div class="row"><h3>${esc(i.title)}</h3><span class="tag ${i.status==='resolved'?'green':'amber'}">${incidentLabels[i.status]}</span></div><p class="small muted">${esc(i.source)} · ${esc(i.date)}</p><p style="margin-top:12px">${esc(i.description)}</p><p class="small muted" style="margin-top:10px">Involucrados: ${esc(memberNames(i.studentIds))}</p><div class="callout"><span class="tag lilac">Sugerencia de Miseño</span><p>${esc(i.recommendation)}</p></div><div class="actions"><button class="btn secondary" data-incident="${i.id}">${i.status==='resolved'?'Ver acuerdos o retomar':'Preparar intervención'}</button></div><div class="timeline">${state.projectEvents.filter(e=>e.incidentId===i.id).map(projectEventCard).join('')}</div></article>`).join('')||'<p class="empty">No hay situaciones de convivencia registradas para este proyecto.</p>'}</div></section>`}
function projects(){ensureProjects();return title('Proyectos','Organización de equipos, seguimiento y convivencia.')+`<div class="toolbar"><label for="project-select" style="margin:0">Proyecto</label><select id="project-select">${Object.entries(projectDefinitions).map(([id,d])=>`<option value="${id}" ${projectId===id?'selected':''}>${d.name}</option>`).join('')}</select><span class="tag green">${projectDefinitions[projectId].subject}</span></div><section class="card project-brief"><div><h2>${projectDefinitions[projectId].name}</h2><p class="muted">${projectDefinitions[projectId].goal}</p></div><div class="small muted">${projectDefinitions[projectId].date}<br>${projectDefinitions[projectId].materials}</div></section>${projectNavigation()}<div id="project-panel">${projectPanel()}</div>`}
function projectPanel(){return ({teams:groupProjectPanel,follow:followProjectPanel,coexist:coexistProjectPanel}[projectTab])()}
function updateProjectPanel(){const el=$('#project-panel');if(el)el.innerHTML=projectPanel();document.querySelectorAll('[data-project-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.projectTab===projectTab)))}
function recordProjectEvent(data){ensureProjects();const event={id:'project-event-'+Date.now()+'-'+state.projectEvents.length,project:projectId,date:new Date().toISOString(),...data};event.studentIds=[...new Set(event.studentIds)];state.projectEvents.unshift(event);persist();return event}
function applyTeamEdit(id,name,members,criterion){const groups=projectTeams();name=name.trim();if(!name)return 'Escribí un nombre para el grupo.';if(members.length<2||members.length>6)return 'Elegí entre 2 y 6 integrantes.';if(new Set(members).size!==members.length||members.some(m=>!pupils.some(p=>p.id===m)))return 'Revisá la selección de alumnos.';const target=groups.find(t=>t.id===id);if(groups.some(t=>t.id!==id&&t.name.toLowerCase()===name.toLowerCase()))return 'Ya hay un grupo con ese nombre.';const others=groups.filter(t=>t.id!==id).map(t=>({...t,members:t.members.filter(m=>!members.includes(m))}));if(others.some(t=>t.members.length===1))return 'El cambio dejaría un equipo con un solo alumno. Elegí otra combinación o reorganizá los grupos.';const affected=[...(target?.members||[]),...members],newId=id||'team-'+Date.now();state.projectGroups[projectId]=[...others.filter(t=>t.members.length),{id:newId,name,members:[...members],criterion:criterion.trim()||'Agrupamiento definido por la docente.'}];selectedTeam=newId;recordProjectEvent({type:target?'Cambio de integrantes':'Creación de grupo',studentIds:affected,text:`${name}: ${memberNames(members)}. ${target?'Equipo anterior: '+memberNames(target.members)+'. ':''}Criterio: ${criterion.trim()||'Definición docente.'}`,followup:'Revisar participación y acuerdos durante la próxima actividad.'});return ''}
function editTeamForm(create=false){const team=create?null:chosenTeam();modal(create?'Crear grupo':'Editar · '+team.name,`<form id="team-edit-form" data-team-id="${team?.id||''}"><label for="team-name">Nombre del grupo</label><input id="team-name" maxlength="50" required value="${esc(team?.name||'')}"><label>Integrantes · Entre 2 y 6</label><div class="member-picker">${pupils.map(p=>`<label class="check"><input type="checkbox" name="team-member" value="${p.id}" ${team?.members.includes(p.id)?'checked':''}><span>${p.name}<small class="muted">${esc(projectTeams().find(t=>t.members.includes(p.id))?.name||'Sin grupo')}</small></span></label>`).join('')}</div><p class="small muted">Al confirmar, los alumnos seleccionados pasan a este equipo. Quienes retires quedan disponibles para reasignar. No se permiten equipos con un solo integrante.</p><label for="team-criterion">Criterio de organización</label><textarea id="team-criterion" maxlength="1000">${esc(team?.criterion||'')}</textarea><div id="team-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="submit">Confirmar integrantes</button><button class="btn ghost" type="button" data-action="close">Cancelar</button></div></form>`)}
function suggestedTeams(){const order=projectId==='huerta'?['sofia','mateo','valentina','isabella','joaquin','nicolas','benjamin','tomasp','bruno','lucia','catalina','felipe','emma','santino','olivia','tomi']:pupils.map(p=>p.id);return [0,1,2,3].map(i=>({id:'suggested-'+projectId+'-'+i,name:['Exploración','Construcción','Comunicación','Organización'][i],members:order.slice(i*4,i*4+4),criterion:['Intereses registrados sobre plantas, animales y experimentos.','Intereses registrados sobre medidas, construcciones y formas.','Narración, lectura y descripción como oportunidades de registro compartido.','Preguntas sobre el entorno, recorridos y tareas de la comunidad.'][i]}))}
function showTeamProposal(){modal('Revisar propuesta de Miseño',`<p class="muted" style="margin-top:14px">La propuesta usa los intereses de las fichas y distribuye roles a rotar. No evalúa compatibilidad personal ni resuelve conflictos.</p>${suggestedTeams().map(t=>`<div class="callout"><h3>${t.name}</h3><p>${esc(memberNames(t.members))}</p><p class="small muted">${esc(t.criterion)}</p></div>`).join('')}<p style="margin-top:16px">Al confirmar, reemplaza los equipos actuales de este proyecto. Las observaciones y situaciones anteriores se conservan.</p><div class="actions"><button class="btn" data-project-action="accept-teams">Confirmar propuesta</button><button class="btn ghost" data-action="close">Conservar grupos actuales</button></div>`)}
function acceptTeamProposal(){const proposal=suggestedTeams();state.projectGroups[projectId]=proposal;selectedTeam=proposal[0].id;recordProjectEvent({type:'Agrupamiento propuesto por Miseño y confirmado por la docente',studentIds:proposal.flatMap(t=>t.members),text:proposal.map(t=>t.name+': '+memberNames(t.members)).join(' · '),followup:'Rotar roles y revisar la participación al cierre.'});$('#dialog').close();updateProjectPanel();toast('Grupos confirmados. Los registros anteriores se conservan.')}
function projectObservation(incidentId=null){const incident=state.projectIncidents.find(i=>i.id===incidentId),team=chosenTeam();modal(incident?'Intervención de convivencia':'Observación · '+team.name,`<p class="muted" style="margin-top:12px">${esc(memberNames(incident?incident.studentIds:team.members))}</p>${incident?`<div class="callout"><strong>${esc(incident.title)}</strong><p>${esc(incident.description)}</p><p><strong>Propuesta de Miseño:</strong> ${esc(incident.recommendation)}</p></div>`:''}<form id="project-observation-form" data-incident-id="${incidentId||''}"><label for="project-observation">${incident?'Qué hiciste y qué acuerdos se alcanzaron':'Qué observaste y qué apoyo diste'}</label><textarea id="project-observation" required maxlength="2000" placeholder="Describí lo observado sin atribuir intenciones."></textarea><label for="project-followup">Próximo seguimiento</label><textarea id="project-followup" required maxlength="1000" placeholder="Cuándo lo retomarás y qué vas a observar."></textarea>${incident?`<label for="incident-status">Estado de la situación</label><select id="incident-status"><option value="followup" selected>En seguimiento</option><option value="open">Pendiente de intervención</option><option value="resolved">Cerrar con acuerdos registrados</option></select><p class="small muted">Registrar una intervención no cierra automáticamente la situación.</p>`:''}<div id="project-observation-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="submit">Guardar intervención</button><button class="btn ghost" type="button" data-action="close">Cancelar</button></div></form>`)}
function saveProjectObservation(text,followup,incidentId=null,status='followup'){text=text.trim();followup=followup.trim();if(!text||!followup)return 'Completá la observación y el próximo seguimiento.';const incident=state.projectIncidents.find(i=>i.id===incidentId);if(incidentId&&!incident)return 'La situación no está disponible.';if(incident&&!Object.keys(incidentLabels).includes(status))return 'Elegí un estado válido.';recordProjectEvent({type:incident?'Intervención de convivencia':'Observación de equipo',text,followup,studentIds:incident?incident.studentIds:chosenTeam().members,incidentId:incident?.id||null,status:incident?status:null});if(incident){incident.status=status;persist()}return ''}
function newIncidentForm(){modal('Registrar situación de convivencia',`<form id="new-incident-form"><label for="incident-title">Título</label><input id="incident-title" required maxlength="100" placeholder="Por ejemplo: desacuerdo en el uso de materiales"><label>Alumnos involucrados</label><div class="member-picker">${pupils.map(p=>`<label class="check"><input type="checkbox" name="incident-member" value="${p.id}"><span>${p.name}</span></label>`).join('')}</div><label for="incident-description">Qué ocurrió</label><textarea id="incident-description" required maxlength="2000"></textarea><div id="incident-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="submit">Registrar situación</button><button class="btn ghost" type="button" data-action="close">Cancelar</button></div></form>`)}
function saveIncident(title,text,ids){title=title.trim();text=text.trim();if(!title||!text||ids.length<2)return 'Completá el título, lo ocurrido y al menos dos alumnos.';if(ids.some(id=>!pupils.some(p=>p.id===id)))return 'Revisá los alumnos seleccionados.';const incident={id:'incident-'+Date.now(),project:projectId,title,description:text,studentIds:[...new Set(ids)],date:new Date().toLocaleString('es-AR'),source:'Docente · Clara López',status:'open',recommendation:'Escuchar a las personas involucradas por separado si hace falta, reconstruir lo ocurrido y acordar una acción concreta con seguimiento.'};state.projectIncidents.unshift(incident);recordProjectEvent({type:'Situación de convivencia registrada',studentIds:incident.studentIds,text:title+': '+text,followup:'Preparar una intervención docente.',incidentId:incident.id});return ''}
// Link one project event into each involved student's intervention view.
const individualInterventions=interventionRecords;
interventionRecords=function(){ensureProjects();const events=state.projectEvents.filter(e=>e.studentIds.includes(student));return individualInterventions()+`<section class="card embedded-history"><h2>Intervenciones en proyectos</h2><div class="timeline">${events.map(e=>projectEventCard(e)+`<button class="link" data-open-project="${e.project}">Ver proyecto →</button>`).join('')||'<p class="empty">No hay intervenciones en proyectos registradas para este alumno.</p>'}</div></section>`};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.projectTab){projectTab=b.dataset.projectTab;updateProjectPanel();b.focus()}if(b.dataset.team){selectedTeam=b.dataset.team;updateProjectPanel()}if(b.dataset.incident)projectObservation(b.dataset.incident);if(b.dataset.openProject){projectId=b.dataset.openProject;projectTab='follow';selectedTeam=state.projectGroups[projectId].find(t=>t.members.includes(student))?.id||state.projectGroups[projectId][0].id;page='projects';render(true)}const a=b.dataset.projectAction;if(a==='new-team')editTeamForm(true);if(a==='edit-team')editTeamForm();if(a==='suggest')showTeamProposal();if(a==='accept-teams')acceptTeamProposal();if(a==='observe')projectObservation();if(a==='new-incident')newIncidentForm()});
document.addEventListener('change',e=>{if(e.target.id==='project-select'){projectId=e.target.value;selectedTeam=projectTeams()[0].id;render()}});
document.addEventListener('submit',e=>{const f=e.target;if(!['team-edit-form','project-observation-form','new-incident-form'].includes(f.id))return;e.preventDefault();let error='';if(f.id==='team-edit-form')error=applyTeamEdit(f.dataset.teamId||null,$('#team-name').value,[...f.querySelectorAll('[name="team-member"]:checked')].map(x=>x.value),$('#team-criterion').value);if(f.id==='project-observation-form')error=saveProjectObservation($('#project-observation').value,$('#project-followup').value,f.dataset.incidentId||null,$('#incident-status')?.value||'followup');if(f.id==='new-incident-form')error=saveIncident($('#incident-title').value,$('#incident-description').value,[...f.querySelectorAll('[name="incident-member"]:checked')].map(x=>x.value));if(error){$(f.id==='team-edit-form'?'#team-error':f.id==='project-observation-form'?'#project-observation-error':'#incident-error').textContent=error;return}$('#dialog').close();updateProjectPanel();toast('Guardado en el proyecto y vinculado a los alumnos.')});

render();
setTimeout(()=>{const splash=$('#splash');splash.hidden=true;},1400);
